// Its commands go between the { and the }.
void setup() {
  // A command is a name, then ( ), then a ;
  // The number inside forward( ) is how many cells to drive.
  forward(1);

  // Turns don't need a number, so their ( ) stay empty, like turnRight();
}

// loop() is for later. Leave it empty for now.
void loop() {
